  $('end-copy').textContent=won?'The morning crew is here. Time to clock out.':`${enemy?.name||'Something'} got into the office. The night shift is over.`;
  $('end-stats').innerHTML=`<div>TIME SURVIVED<strong>${timeText(state.elapsed).replace(/<[^>]*>/g,'')} AM</strong></div><div>POWER LEFT<strong>${Math.ceil(state.power)}%</strong></div>`;
}
function advanceEnemy(enemy){
  const next=enemy.step+1;
  if(next>=enemy.route.length){
    const closed=state.doors[enemy.side];
    if(closed){
      enemy.step=Math.max(1,enemy.step-1);setEnemyPosition(enemy);
      showToast(`THUD — ${enemy.side.toUpperCase()} DOOR HELD`,2300);
      enemy.next=30+Math.random()*20;
    }else{
      showToast(`MOVEMENT DETECTED — ${enemy.side.toUpperCase()} DOOR`,3000);
      enemy.next=10;
      enemy.attackPending=true;
    }
  }else{
    enemy.step=next;setEnemyPosition(enemy);
    const room=enemy.route[enemy.step];
    if(room==='leftDoor'||room==='rightDoor'){
      enemy.next=10;enemy.attackPending=true;
      showToast(`MOVEMENT DETECTED — ${enemy.side.toUpperCase()} DOOR`,3000);
    }else{
      showToast(`CAMERA MOVEMENT — ${enemy.name.toUpperCase()} IS IN ${roomById[room].name}`,2100);
      enemy.next=Math.max(36,67-state.elapsed*.075)+Math.random()*23;
    }
  }
}
function updateEnemies(dt){
  for(const enemy of enemies){
    if(enemy.attackPending){
      if(state.doors[enemy.side]){
        enemy.attackPending=false;enemy.step=Math.max(1,enemy.step-1);setEnemyPosition(enemy);enemy.next=30+Math.random()*22;
        showToast(`THUD — ${enemy.side.toUpperCase()} DOOR HELD`,2400);
      }else{
        enemy.next-=dt;
        if(enemy.next<=0){endGame(false,enemy);return;}
      }
    }else{
      enemy.next-=dt;
      if(enemy.next<=0)advanceEnemy(enemy);
    }
  }
}
function resetGame(){
  state.running=false;state.ended=false;state.elapsed=0;state.power=100;state.monitor=false;state.cam='stage';state.blackout=0;
